head.script:
scwin.btn_update_onclick = function() {
    var grdObj = $w.comp[$p.id+'grd_dataList1'];
    var checkData = grdObj.getCheckedIndex(0);
    for (var idx = 0; idx < checkData.length; idx++) {
        var gridIndex = checkData[idx];
        checkData[idx] = grdObj.getRealRowIndex(gridIndex);
    }
    for (var idx = 0; idx < checkData.length; idx++) {
        var rowIndex = checkData[idx];
        $w.data[$p.id+'dlt_dataList1'].modifyRowStatus(rowIndex, "U");
        $w.data[$p.id+'dlt_dataList1'].setCellData(rowIndex, "sRowStatus", "U");
        grdObj.setCellChecked(rowIndex, 0, false);
    }
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 임의로 몇개의 row 를 체크한 후 update 버튼을 클릭한다.
    //Check any row in your browser and click the update button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_dataList1_cell_0_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#btn_update a')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 임의로 체크한 row 가 필터조건에서 제외된다.
    //Randomly checked rows are excluded from filter conditions.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_dataList1_cell_0_1').text() == '21'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_dataList1_cell_0_2').text() == '22'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_dataList1_cell_0_3').text() == '23'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 전체체크 아이콘을 클릭한다.
    //Click the Check All icon.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_dataList1_column3').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 남겨진 row 항목들이 전체체크된다.
    //The remaining row items are checked in full.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_dataList1_cell_0_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_dataList1_cell_1_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_dataList1_cell_2_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_dataList1_cell_3_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_dataList1_cell_4_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Jan-2018       
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
